  const заголовок = источник.лист;
  const {doc, итог: и} = построитьСхему(р, заголовок);
  const т = 'Схема «' + заголовок + '»: листов ' + и.листов + ', областей ' + и.областей + (и.итогов ? ' (с итогами)' : '') + ', фигур ' + и.фигур + ', связей ' + и.связей
    + (и.наДругие ? ' (на другие листы — ' + и.наДругие + ')' : '') + (и.ненайдено.length ? '; не найдено: ' + и.ненайдено.join(', ') : '')
    + (и.пропущено ? '; строк без имени: ' + и.пропущено : '');
  панель.поле('итог', [{текст: т, цвет: и.ненайдено.length ? '#b35c00' : '#2b8a3e'}]);
  лист(источник.лист).запомнить(ПАМЯТЬ, {источник: источник.источник, область: источник.область || null,
    роли: {имя: р.имя || НЕТ, связи: р.связи || НЕТ, лист: р.лист || НЕТ, область1: р.область1 || НЕТ, область2: р.область2 || НЕТ, статус: р.статус || НЕТ,
           цвет: р.цвет || НЕТ, описание: р.описание, итоги: р.итоги, рабочий: р.рабочий}, раскладка: р.раскладка, заголовки: р.заголовки, когда: new Date().toLocaleString('ru-RU')});
  /* в открытую схему — новыми листами; Диаграммы ещё не открыты — новой схемой */
  const о = await файл.открытьВПриложении(заголовок.replace(/[\\/:*?"<>|]+/g, ' ').trim() + '.plsv', JSON.stringify(doc), {вОткрытый: true});
  панель.сообщение(т + (о.открыто ? ' — в Диаграммах' : о.сохранено ? ' — сохранена: ' + о.имя : ' — не открыта'));
  return Object.assign({}, и, {открыто: !!о.открыто, сохранено: !!о.сохранено, doc});
}
async function Построить(){
  try {
    const п = параметры({});
    if(!столбцы.length || !источник){ await прочитатьТаблицу(п); показатьСтолбцы(лист(источник.лист).память(ПАМЯТЬ)); }
    else await прочитатьТаблицу(п, источник);
    return await построитьИОткрыть(роли(п));
  } catch(e){ панель.поле('итог', [{текст: e.message, цвет: '#c92a2a'}]); панель.сообщение(e.message); throw e; }
}
/* по ролям, запомненным в листе, — без панели и выбора */
async function Обновить(){
  try {
    const в = книга.выделение, имяЛиста = в && в.лист;
    const м = имяЛиста ? лист(имяЛиста).память(ПАМЯТЬ) : null;
    if(!м) throw new Error('На листе «' + имяЛиста + '» схему ещё не строили — нажмите «Прочитать столбцы», затем «Построить схему»');
    await прочитатьТаблицу({}, {лист: имяЛиста, источник: м.источник, область: м.область});
    показатьСтолбцы(м);
    return await построитьИОткрыть(роли(Object.assign({}, м.роли, {раскладка: м.раскладка, заголовки: м.заголовки})));
  } catch(e){ панель.поле('итог', [{текст: e.message, цвет: '#c92a2a'}]); панель.сообщение(e.message); throw e; }
}
